//! miniq: a small in-memory message queue driven by JSON commands.
//!
//! [`Service`] holds all state and turns one input line into one response
//! value; the binary only moves lines between stdin and stdout.

mod error;
mod params;
mod service;

pub use error::{Code, Error};
pub use service::Service;
EOF
cat > src/service.rs <<'EOF'
//! The service: request parsing, dispatch and response shaping.

use serde_json::{json, Map, Value};

use crate::error::{Error, Result};
use crate::params::Params;

/// Largest value of the virtual clock a command may add up to; behaviour past
/// it is unspecified, so `Tick` simply saturates.
const MAX_TICK: i64 = 1_209_600;

#[derive(Default)]
pub struct Service {
    now: u64,
}

impl Service {
    pub fn new() -> Self {
        Self::default()
    }

    /// Runs one input line (without its `\n`) and returns the response object.
    pub fn handle_line(&mut self, line: &[u8]) -> Value {
        match self.execute(line) {
            Ok(result) => {
                let mut response = Map::new();
                response.insert("ok".into(), Value::Bool(true));
                response.extend(result);
                Value::Object(response)
            }
            Err(e) => json!({
                "ok": false,
                "error": {"code": e.code.as_str(), "message": e.message},
            }),
        }
    }

    fn execute(&mut self, line: &[u8]) -> Result<Map<String, Value>> {
        let text = std::str::from_utf8(line)
            .map_err(|_| Error::invalid_request("line is not valid UTF-8"))?;
        let Ok(Value::Object(members)) = serde_json::from_str::<Value>(text) else {
            return Err(Error::invalid_request("line is not a JSON object"));
        };
        let Some(Value::String(command)) = members.get("Command") else {
            return Err(Error::invalid_request("Command must be a string"));
        };
        let params = Params::new(&members);
        match command.as_str() {
            "Tick" => self.tick(&params),
            other => Err(Error::invalid_request(format!("unknown command {other}"))),
        }
    }

    fn tick(&mut self, params: &Params) -> Result<Map<String, Value>> {
        params.require("Seconds")?;
        let seconds = params.integer("Seconds", 0..=MAX_TICK)?.unwrap_or(0);
        self.now += seconds as u64;
        Ok(object([("Now", json!(self.now))]))
    }
}

/// Builds a result object from `(member, value)` pairs.
pub(crate) fn object<const N: usize>(members: [(&str, Value); N]) -> Map<String, Value> {
    members.into_iter().map(|(k, v)| (k.to_owned(), v)).collect()
}
EOF
cat > src/main.rs <<'EOF'
use std::io::{self, BufRead, Write};
use std::process::ExitCode;

use miniq::Service;

fn main() -> ExitCode {
    match run() {
        Ok(()) => ExitCode::SUCCESS,
        Err(e) => {
            eprintln!("miniq: {e}");
            ExitCode::FAILURE
        }
    }
}

/// Answers every input line with exactly one response line, flushing each
/// response before the next line is read.
fn run() -> io::Result<()> {
    let mut input = io::stdin().lock();
    let mut output = io::stdout().lock();
    let mut service = Service::new();
    let mut line = Vec::new();
    loop {
        line.clear();
        if input.read_until(b'\n', &mut line)? == 0 {
            return Ok(());
        }
        if line.last() == Some(&b'\n') {
            line.pop();
        }
        let response = service.handle_line(&line);
        serde_json::to_writer(&mut output, &response)?;
        output.write_all(b"\n")?;
        output.flush()?;
    }
}
EOF
cat > tests/protocol.rs <<'EOF'
//! End-to-end tests of the line protocol through the real binary.

use std::io::Write;
use std::process::{Command, Stdio};

fn run(input: &[u8]) -> Vec<String> {
    let mut child = Command::new(env!("CARGO_BIN_EXE_miniq"))
        .stdin(Stdio::piped())
        .stdout(Stdio::piped())
        .spawn()
        .unwrap();
    child.stdin.take().unwrap().write_all(input).unwrap();
    let out = child.wait_with_output().unwrap();
    assert!(out.status.success());
    String::from_utf8(out.stdout).unwrap().lines().map(str::to_owned).collect()
}

#[test]
fn every_line_gets_one_response_in_order() {
    let lines = run(b"{\"Command\":\"Tick\",\"Seconds\":5}\n\n{\"Command\":\"Tick\",\"Seconds\":1}\n");
    assert_eq!(lines.len(), 3);
    assert!(lines[0].contains("\"Now\":5"));
    assert!(lines[1].contains("InvalidRequest"));
    assert!(lines[2].contains("\"Now\":6"));
}

#[test]
fn final_line_without_newline_counts() {
    assert_eq!(run(b"{\"Command\":\"Tick\",\"Seconds\":1}").len(), 1);
    assert!(run(b"").is_empty());
}

#[test]
fn invalid_utf8_is_an_invalid_request_and_processing_continues() {
    let lines = run(b"\xff\xfe\n{\"Command\":\"Tick\",\"Seconds\":2}\n");
    assert!(lines[0].contains("InvalidRequest"));
    assert!(lines[1].contains("\"Now\":2"));
}
EOF
cargo test 2>&1 | grep -E "test result|error|warning|FAILED" ; git add -A && git commit -qm "Scaffold miniq: line protocol, error codes, typed params, Tick

The protocol loop and the parameter/error plumbing are shared by every
command, so they land first with the simplest command (Tick) to exercise
them end to end. serde_json's arbitrary_precision keeps number literals so
30.0 and 3e1 can be rejected as non-integers.

