                break;
            }
            // A newer window for the same id must survive.
            if self.accepted.get(id).is_some_and(|a| a.at == *at) {
                self.accepted.remove(id);
            }
            self.accepted_order.pop_front();
        }
        self.accepted_order.push_back((now, deduplication_id.clone()));
        self.accepted.insert(deduplication_id, Accepted { at: now, message_id, sequence_number });
    }
}
