    receive(&mut s, "q", 1);
    s.ok(json!({"Command": "PurgeQueue", "QueueName": "q"}));
    let del = json!({"Command": "DeleteMessage", "QueueName": "q", "ReceiptHandle": "r-1"});
    assert_eq!(s.err(del.clone()), "ReceiptHandleExpired");
    send(&mut s, "q", "b");
    receive(&mut s, "q", 1);
    s.ok(json!({"Command": "DeleteQueue", "QueueName": "q"}));
    s.create("q", json!({}));
